function bname(c,id){var b=c.db.bookings.find(function(x){return x.id===id});return b?b.customer:"Unknown renter"}
function field(c,label,name,control,opts){opts=opts||{};var help=opts.help?'<small class="form-help">'+e(c,opts.help)+'</small>':'';return '<div class="field '+(opts.full?"full":"")+'"><label for="v2-'+e(c,name)+'">'+e(c,label)+'</label>'+control.replace("__ID__","v2-"+e(c,name))+help+'</div>'}
function inp(c,label,name,placeholder,opts){opts=opts||{};return field(c,label,name,'<input id="__ID__" name="'+e(c,name)+'" '+(opts.type?'type="'+opts.type+'"':'type="text"')+' '+(opts.required?'required ':'')+(opts.min?'min="'+opts.min+'" ':'')+'placeholder="'+e(c,placeholder||"")+'" value="'+e(c,opts.value||"")+'">',opts)}
function select(c,label,name,arr,value,opts){return field(c,label,name,'<select id="__ID__" name="'+e(c,name)+'">'+arr.map(function(a){var val=Array.isArray(a)?a[0]:a,display=Array.isArray(a)?a[1]:a;return '<option value="'+e(c,val)+'" '+(String(val)===String(value)?"selected":"")+'>'+e(c,display)+'</option>'}).join("")+'</select>',opts)}
function area(c,label,name,ph){return field(c,label,name,'<textarea id="__ID__" name="'+e(c,name)+'" rows="3" placeholder="'+e(c,ph)+'"></textarea>',{full:true})}
function info(c,title,desc,kind){return '<div class="notice '+(kind||"")+'">'+icon(c,"info")+'<div><strong>'+e(c,title)+'</strong><p>'+e(c,desc)+'</p></div></div>'}
function thRow(headers){return '<thead><tr>'+headers.map(function(x){return '<th>'+x+'</th>'}).join("")+'</tr></thead>'}
function table(headers,rows){return '<div class="card table-card"><div class="table-wrap"><table>'+thRow(headers)+'<tbody>'+rows.join("")+'</tbody></table></div></div>'}
function tr(c,cells){return '<tr>'+cells.map(function(x){return '<td>'+x+'</td>'}).join("")+'</tr>'}
function page(c,title,desc,cta,act,contents){return c.header(title,desc,cta||"New booking",act||"new-booking")+c.demo()+contents}
function section(title,subtitle,body){return '<section class="card section-block"><div class="card-header"><div><h2>'+title+'</h2><p>'+subtitle+'</p></div></div>'+body+'</section>'}
function statusCount(db,k,status){return db[k].filter(function(x){return x.status===status}).length}
function dataRow(c,left,right){return '<div class="task-row"><span class="muted">'+e(c,left)+'</span><strong style="margin-left:auto">'+e(c,right)+'</strong></div>'}
