function dateVal(s){var d=new Date(s+"T12:00:00");return Number.isNaN(d.getTime())?null:d}
function hasBookingOverlap(c,v,from,to){return c.db.bookings.some(function(b){if(b.vehicle!==v||b.status==="Completed"||b.status==="Cancelled")return false;var m=b.date.match(/(\d{1,2})\s+([A-Za-z]{3})/),months=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];if(!m)return false;var st=new Date(2026,months.indexOf(m[2]),+m[1],12);var en=new Date(st);en.setDate(st.getDate()+(+b.days||1));return st<to&&from<en})}
function conflicts(c,v,from,to){return hasBookingOverlap(c,v,from,to)||c.db.holds.some(function(h){return h.vehicle===v&&h.status==="Active"&&dateVal(h.start)<to&&from<new Date(dateVal(h.end).getTime()+86400000)})}
function availability(c){var days=Array.from({length:7},function(_,i){return new Date(2026,9,13+i)});var head=["Vehicle"].concat(days.map(function(x){return x.toLocaleDateString("en-GB",{weekday:"short",day:"numeric"})}));
var rows=c.db.vehicles.map(function(v){return tr(c,['<div class="row-title">'+e(c,v.name)+'</div><small class="muted">'+e(c,v.plate)+' · '+e(c,v.location)+'</small>'].concat(days.map(function(day){var start=new Date(day),end=new Date(day);end.setDate(end.getDate()+1);var held=c.db.holds.some(function(h){return h.vehicle===v.id&&h.status==="Active"&&dateVal(h.start)<end&&start<new Date(dateVal(h.end).getTime()+86400000)});var occupied=hasBookingOverlap(c,v.id,start,end);return '<span class="schedule-cell '+(v.status==="Maintenance"||!v.compliant?"blocked":occupied?"occupied":held?"held":"free")+'">'+(v.status==="Maintenance"||!v.compliant?"Blocked":occupied?"Booked":held?"Hold":"Ready")+'</span>'})))});
return page(c,"Availability & allocations","Every vehicle first, then narrow by car and time.","Create availability hold","v2:open:hold",
'<div class="legend-line"><span class="schedule-cell free">Ready</span><span class="schedule-cell occupied">Booked</span><span class="schedule-cell held">Hold</span><span class="schedule-cell blocked">Blocked</span></div>'+table(head,rows)+
'<div class="page-toolbar"><div><h2>Operational holds</h2><p class="muted tiny">Active holds appear first, then released holds.</p></div>'+bt(c,"+ Add hold","v2:open:hold",null,"primary")+'</div>'+
(c.db.holds.length?table(["Vehicle","From","Through","Reason","Status","Action"],c.db.holds.slice().sort(function(a,b){return (a.status==="Active"?0:1)-(b.status==="Active"?0:1)}).map(function(h){var v=chosen(c,h.vehicle);return tr(c,[e(c,v?v.name:"Vehicle"),e(c,h.start),e(c,h.end),e(c,h.reason),badge(c,h.status),h.status==="Active"?tiny(c,"Release","v2:release-hold",h.id):"Released"])})):info(c,"No manually created holds","Use Create availability hold to reserve a period for servicing, owner use or other operational restrictions."))+
info(c,"Conflict-friendly errors","Overlapping periods are explained by car name and dates. Backend allocation IDs are never shown in customer-facing messages."))}
